const fxRates = $('Fetch FX Rates').first().json.rates || {};

const commodity = $input.item.json.commodity;
const dataArr = $input.item.json.data || [];

let rawContext = `Dữ liệu thị trường cho ${commodity} trong 48h qua:\n`;
let sources = [];

dataArr.forEach(row => {
  rawContext += `- [${row.source}] ${row.metric}: ${row.value} ${row.unit} (Thời gian: ${row.period})\n`;
  sources.push({
    source: row.source,
    metric: row.metric,
    value: row.value,
    date: row.period
  });
});

rawContext += `\nTỷ giá ngoại tệ tham chiếu (so với USD): ${JSON.stringify(fxRates)}`;

return {
  commodity: commodity,
  raw_context: rawContext,
  sources_json: sources
};

// Strip <think>...</think> blocks from reasoning model output
const rawContent = $input.item.json.choices[0].message.content;
// Match <think> up to </think> OR end of string if cut off
const cleanContent = rawContent.replace(/<think>[\s\S]*?(<\/think>|$)/gi, '').trim();

return {
  bulletin_text: cleanContent,
  commodity: $('Code (Prepare RAG Context)').item.json.commodity,
  sources_json: $('Code (Prepare RAG Context)').item.json.sources_json
};
